 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            # The scattered background is isolated; the solid monochrome figures are sizeable components.
            if len(cells) >= 8:
                objects.append((len(cells), color))
    if not objects:
        return []
    side = len(objects)
    color = max(objects)[1]
    return [[color for _ in range(side)] for _ in range(side)]
